import pytest
from candidate import correct_bracketing

class TestCorrectBracketing:

    def test_correct_bracketing_true_normalcase(self):
        assert correct_bracketing("(()())") == True

    def test_correct_bracketing_true_empty(self):
        assert correct_bracketing("") == True

    def test_correct_bracketing_false_normalcase(self):
        assert correct_bracketing("(()") == False

    def test_correct_bracketing_false_mismatched(self):
        assert correct_bracketing("())") == False

    def test_correct_bracketing_false_wrongorder(self):
        assert correct_bracketing("())(") == False

    def test_correct_bracketing_false_extraclosing(self):
        assert correct_bracketing("()))") == False

    def test_correct_bracketing_true_nobrackets(self):
        assert correct_bracketing("") == True
